SELECT date, printf('%.5f',fx) AS fx, printf('%.8f',(sum(quantity*close_HKD)*fx+final_cash)/500000.0) AS estimate, printf('%.8f',official_basket_NAV/500000.0) AS official, printf('%+.4f',sum(quantity*close_HKD)*fx+final_cash-official_basket_NAV) AS error, CASE WHEN net_baskets IS NULL THEN '—' ELSE printf('%+.0f',net_baskets) END AS net FROM daily_inputs GROUP BY date ORDER BY date;
